export default function DiscussionPage() {
  const [activeTab, setActiveTab] = useState("All")
  const [selectedTags, setSelectedTags] = useState<string[]>([])

  const toggleTag = (tag: string) => {
    setSelectedTags((prev) => (prev.includes(tag) ? prev.filter((t) => t !== tag) : [...prev, tag]))
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
        <div>
          <h1 className="text-2xl font-bold text-foreground">Discussion</h1>
          <p className="text-muted-foreground">Join the conversation with the community</p>
        </div>
        <Button className="rounded-xl bg-primary text-primary-foreground hover:bg-primary/90 shadow-md">
          <Plus className="mr-2 h-4 w-4" />
          Start New Thread
        </Button>
      </div>

      {/* Search */}
      <div className="relative">
        <Search className="absolute left-4 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
        <Input
          type="search"
          placeholder="Search discussions..."
          className="w-full rounded-xl border-none bg-card pl-11 py-5 shadow-sm focus-visible:ring-primary"
        />
      </div>

      {/* Tabs */}
      <div className="flex gap-2 overflow-x-auto pb-2">
        {tabs.map((tab) => (
          <Button
            key={tab}
            variant={activeTab === tab ? "default" : "ghost"}
            className={`rounded-xl px-4 ${
              activeTab === tab
                ? "bg-primary text-primary-foreground shadow-md"
                : "bg-card hover:bg-muted text-foreground"
            }`}
            onClick={() => setActiveTab(tab)}
          >
            {tab}
          </Button>
        ))}
      </div>

      {/* Filter Tags */}
      <div className="flex flex-wrap gap-2">
        {filterTags.map((tag) => (
          <Badge
            key={tag}
            variant="secondary"
            className={`cursor-pointer rounded-full px-3 py-1 text-sm font-medium transition-all ${
              selectedTags.includes(tag)
                ? "bg-primary text-primary-foreground"
                : "bg-secondary text-secondary-foreground hover:bg-primary/20"
            }`}
            onClick={() => toggleTag(tag)}
          >
            {tag}
          </Badge>
        ))}
      </div>

      {/* Main Content Grid */}
      <div className="grid gap-6 lg:grid-cols-3">
        {/* Thread List */}
        <div className="space-y-4 lg:col-span-2">
          {threads.map((thread) => (
            <ThreadCard key={thread.id} {...thread} />
          ))}
        </div>

        {/* Sidebar */}
        <div className="space-y-6">
          <PopularThreads />
          <TopContributors />
          <WatchedTopics />
        </div>
      </div>
    </div>
  )
}
