import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar"
import { Badge } from "@/components/ui/badge"
import { Card, CardContent } from "@/components/ui/card"
import { MessageSquare, Eye, Clock } from "lucide-react"
import Link from "next/link"

interface ThreadCardProps {
  id: string
  title: string
  preview: string
  author: {
    name: string
    avatar: string
    initials: string
  }
  tags: string[]
  replies: number
  views: number
  lastActive: string
}

export function ThreadCard({ id, title, preview, author, tags, replies, views, lastActive }: ThreadCardProps) {
  return (
    <Link href={`/discussion/${id}`}>
      <Card className="group rounded-2xl border-none bg-card shadow-sm transition-all hover:shadow-md hover:-translate-y-0.5">
        <CardContent className="p-5">
          <div className="flex gap-4">
            <Avatar className="h-10 w-10 border-2 border-primary/30">
              <AvatarImage src={author.avatar || "/placeholder.svg"} />
              <AvatarFallback className="bg-primary/20 text-primary-foreground text-sm">
                {author.initials}
              </AvatarFallback>
            </Avatar>

            <div className="flex-1 min-w-0">
              <h3 className="font-semibold text-foreground group-hover:text-[#AAC4F5] transition-colors line-clamp-1">
                {title}
              </h3>
              <p className="mt-1 text-sm text-muted-foreground line-clamp-2">{preview}</p>

              <div className="mt-3 flex flex-wrap items-center gap-2">
                {tags.map((tag) => (
                  <Badge
                    key={tag}
                    variant="secondary"
                    className="rounded-full bg-secondary px-2 py-0.5 text-xs font-medium text-secondary-foreground"
                  >
                    {tag}
                  </Badge>
                ))}
              </div>

              <div className="mt-3 flex items-center gap-4 text-xs text-muted-foreground">
                <span className="flex items-center gap-1">
                  <MessageSquare className="h-3.5 w-3.5" />
                  {replies} replies
                </span>
                <span className="flex items-center gap-1">
                  <Eye className="h-3.5 w-3.5" />
                  {views} views
                </span>
                <span className="flex items-center gap-1">
                  <Clock className="h-3.5 w-3.5" />
                  {lastActive}
                </span>
              </div>
            </div>
          </div>
        </CardContent>
      </Card>
    </Link>
  )
}
